969:   const speed = Math.hypot(player.vel.x, player.vel.z);
970:   if (player.onGround) {
971:     player.bobPhase += dt * speed * 1.65;
972:     player.bob = Math.sin(player.bobPhase * 2) * 0.026 * Math.min(1, speed / 4);
973:   }
974:   const shake = game.shake * game.shake;
