979:   const strafe = (keys.has('KeyD') ? 1 : 0) - (keys.has('KeyA') ? 1 : 0);
980:   const targetRoll = -strafe * 0.012;
981:   player.roll = lerp(player.roll, targetRoll, 1 - Math.exp(-8 * dt));
982:   camera.rotation.set(
983:     player.pitch + game.recoil + sy * 0.15,
