997: function resolveCollisions() {
998:   for (const c of world.colliders) {
999:     if (c.type === 'circle') {
1000:       const dx = player.pos.x - c.x;
1001:       const dz = player.pos.z - c.z;
1002:       const d = Math.hypot(dx, dz);
1003:       const min = c.r + player.radius;
1004:       if (d < min && d > 0.0001) {
1005:         player.pos.x = c.x + (dx / d) * min;
1006:         player.pos.z = c.z + (dz / d) * min;
1007:       }
1008:     } else {
1009:       const cos = Math.cos(c.rot);
1010:       const sin = Math.sin(c.rot);
1011:       const dx = player.pos.x - c.x;
1012:       const dz = player.pos.z - c.z;
1013:       const lx = dx * cos + dz * sin;
1014:       const lz = -dx * sin + dz * cos;
1015:       const hx = c.halfW + player.radius;
1016:       const hz = c.halfD + player.radius;
1017:       if (Math.abs(lx) < hx && Math.abs(lz) < hz) {
1018:         const ox = hx - Math.abs(lx);
1019:         const oz = hz - Math.abs(lz);
1020:         let nlx = lx;
1021:         let nlz = lz;
1022:         if (ox < oz) nlx = Math.sign(lx || 1) * hx;
1023:         else nlz = Math.sign(lz || 1) * hz;
1024:         player.pos.x = c.x + nlx * cos - nlz * sin;
1025:         player.pos.z = c.z + nlx * sin + nlz * cos;
1026:       }
1027:     }
1028:   }
1029:   player.pos.x = clamp(player.pos.x, -29.2, 29.2);
1030:   player.pos.z = clamp(player.pos.z, -29.2, 29.2);
1031: }
