1033: function updatePlayer(dt) {
1034:   const forward = (keys.has('KeyW') ? 1 : 0) - (keys.has('KeyS') ? 1 : 0);
1035:   const strafe = (keys.has('KeyD') ? 1 : 0) - (keys.has('KeyA') ? 1 : 0);
1036:   let mx = strafe;
1037:   let mz = -forward;
1038:   if (isTouch) {
1039:     mx += touchMove.x;
1040:     mz += touchMove.y;
1041:     if (Math.hypot(mx, mz) > 1) {
1042:       const l = Math.hypot(mx, mz);
1043:       mx /= l; mz /= l;
1044:     }
1045:   }
1046:   const sprint = keys.has('ShiftLeft') || keys.has('ShiftRight');
1047:   const speed = sprint ? 7.4 : 5.1;
1048:   const cos = Math.cos(player.yaw);
1049:   const sin = Math.sin(player.yaw);
1050:   // forward is -Z, right is +X
1051:   const desiredX = (mx * cos + mz * sin) * speed;
1052:   const desiredZ = (-mx * sin + mz * cos) * speed;
1053:   const accel = player.onGround ? 12 : 3;
1054:   player.vel.x = lerp(player.vel.x, desiredX, 1 - Math.exp(-accel * dt));
1055:   player.vel.z = lerp(player.vel.z, desiredZ, 1 - Math.exp(-accel * dt));
1056:   player.vel.y -= 18 * dt;
1057:   player.pos.x += player.vel.x * dt;
1058:   player.pos.z += player.vel.z * dt;
1059:   player.pos.y += player.vel.y * dt;
1060:   if (player.pos.y <= 0) {
1061:     player.pos.y = 0;
1062:     player.vel.y = 0;
1063:     player.onGround = true;
1064:   }
1065:   resolveCollisions();
1066: 
1067:   // nudge props out of the way
1068:   for (const prop of props) {
1069:     if (prop.held) continue;
1070:     const dx = prop.group.position.x - player.pos.x;
1071:     const dz = prop.group.position.z - player.pos.z;
1072:     const d = Math.hypot(dx, dz);
1073:     const min = prop.radius + player.radius;
1074:     if (d < min && d > 0.001) {
1075:       const push = (min - d) * 0.7;
1076:       prop.group.position.x += (dx / d) * push;
1077:       prop.group.position.z += (dz / d) * push;
1078:       if (Math.hypot(player.vel.x, player.vel.z) > 1) {
1079:         prop.velocity.x += (dx / d) * 1.2;
1080:         prop.velocity.z += (dz / d) * 1.2;
1081:       }
1082:     }
1083:   }
1084: }
