1340: function updateProps(dt) {
1341:   for (const prop of props) {
1342:     prop.hitCooldown = Math.max(0, prop.hitCooldown - dt);
1343:     if (prop.held) continue;
1344:     const prevX = prop.group.position.x;
1345:     const prevY = prop.group.position.y;
1346:     const prevZ = prop.group.position.z;
1347:     prop.velocity.y -= 19 * dt;
1348:     prop.group.position.addScaledVector(prop.velocity, dt);
1349:     if (prop.group.position.y - prop.halfHeight <= 0.005) {
1350:       prop.group.position.y = prop.halfHeight;
1351:       if (prop.velocity.y < 0) prop.velocity.y *= -0.28;
1352:       if (Math.abs(prop.velocity.y) < 0.7) prop.velocity.y = 0;
1353:       prop.velocity.x *= Math.pow(0.1, dt * 3);
1354:       prop.velocity.z *= Math.pow(0.1, dt * 3);
1355:       prop.angular.multiplyScalar(Math.exp(-2.4 * dt));
1356:     }
1357:     if (Math.abs(prop.group.position.x) > 32) {
1358:       prop.group.position.x = Math.sign(prop.group.position.x) * 32;
1359:       prop.velocity.x *= -0.35;
1360:     }
1361:     if (Math.abs(prop.group.position.z) > 32) {
1362:       prop.group.position.z = Math.sign(prop.group.position.z) * 32;
1363:       prop.velocity.z *= -0.35;
1364:     }
1365: 
1366:     // bounce off static cover
1367:     if (prop.group.position.y < 3.1) {
1368:       for (const c of world.colliders) {
1369:         if (c.type === 'circle') {
1370:           const dx = prop.group.position.x - c.x;
1371:           const dz = prop.group.position.z - c.z;
1372:           const d = Math.hypot(dx, dz);
1373:           const min = c.r + prop.radius;
1374:           if (d < min && d > 0.0001) {
1375:             const nx = dx / d;
1376:             const nz = dz / d;
1377:             prop.group.position.x = c.x + nx * min;
1378:             prop.group.position.z = c.z + nz * min;
1379:             const dot = prop.velocity.x * nx + prop.velocity.z * nz;
1380:             if (dot < 0) {
1381:               prop.velocity.x -= 1.55 * dot * nx;
1382:               prop.velocity.z -= 1.55 * dot * nz;
1383:               prop.velocity.multiplyScalar(0.62);
1384:             }
1385:           }
1386:         } else {
1387:           const cos = Math.cos(c.rot);
1388:           const sin = Math.sin(c.rot);
1389:           const dx = prop.group.position.x - c.x;
1390:           const dz = prop.group.position.z - c.z;
1391:           const lx = dx * cos + dz * sin;
1392:           const lz = -dx * sin + dz * cos;
1393:           const hx = c.halfW + prop.radius;
1394:           const hz = c.halfD + prop.radius;
1395:           if (Math.abs(lx) < hx && Math.abs(lz) < hz) {
1396:             const ox = hx - Math.abs(lx);
1397:             const oz = hz - Math.abs(lz);
1398:             let nlx = 0;
1399:             let nlz = 0;
1400:             let nlxPos = lx;
1401:             let nlzPos = lz;
1402:             if (ox < oz) { nlx = Math.sign(lx || 1); nlxPos = nlx * hx; }
1403:             else { nlz = Math.sign(lz || 1); nlzPos = nlz * hz; }
1404:             prop.group.position.x = c.x + nlxPos * cos - nlzPos * sin;
